#!/usr/bin/env python3
"""Render data into the existing static pages; package only public assets."""
from pathlib import Path
from html import escape as e
from datetime import date
import argparse, importlib.util, json, re, shutil, hashlib
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('portfolio_content',ROOT/'site/content.py'); c=importlib.util.module_from_spec(spec);spec.loader.exec_module(c)
def link(url,label,cls=''):
 return f'<a href="{e(url,quote=True)}"'+(f' class="{cls}"' if cls else '')+f'>{e(label)}</a>'
def date_label(s): return date.fromisoformat(s).strftime('%b %d, %Y').replace(' 0',' ')
def heading(kicker,title,body=''):
 return f'<div class="section-heading"><p class="eyebrow">{e(kicker)}</p><h2>{e(title)}</h2>'+(f'<p>{e(body)}</p>' if body else '')+'</div>'
def section(body,alt=False,id=''):
 return f'<section class="section'+(' alt' if alt else '')+'"'+(f' id="{id}"' if id else '')+f'><div class="container">{body}</div></section>'
def hero(kicker,title,body,extra=''):
 return f'<section class="section page-hero"><div class="container"><p class="eyebrow">{e(kicker)}</p><h1>{e(title)}</h1><p class="page-intro">{e(body)}</p>{extra}</div></section>'
def pubcard(p,level=3):
 return f'<article class="project-card publication" data-filter-item="{e(p["publisher"],quote=True)}" id="{p["id"]}"><p class="project-meta">{e(p["publisher"])} · <time datetime="{p["date"]}">{date_label(p["date"])}</time></p><h{level}>{link(p["url"],p["title"])}</h{level}><p class="byline">{e(p["byline"])}</p><p>{e(p["summary"])}</p>{link(p["url"],'Read on '+p['publisher'],'text-link')}</article>'
def filters(values,label):
 return '<div class="filter-controls" hidden role="group" aria-label="'+label+'">'+''.join(f'<button type="button" data-filter="{e(v,quote=True)}" aria-pressed="{str(i==0).lower()}">{e(v)}</button>' for i,v in enumerate(['All']+values))+'</div><p class="filter-status" role="status" aria-live="polite"></p>'
