def build(output):
 renderers={'index':home,'projects':projects,'writing':writing,'speaking':speaking,'service':service,'leadership':leadership,'about':about,'resume':resume}
 for template in sorted((ROOT/'site/templates').glob('*.html')):
  text=template.read_text(); name=template.stem
  if name in renderers:
   text=re.sub(r'<main\b[^>]*>.*?</main>',lambda _: '<main id="main"'+(' class="resume-page"' if name=='resume' else '')+'>'+renderers[name]()+'</main>',text,flags=re.S)
  text=text.replace('Staff Software Engineer','Senior Software Engineer').replace('Gujarat Technical University','Gujarat Technological University')
  # Keep the historical title in the dated experience entry.
  text=text.replace('Previously MTS1 / Senior Software Engineer','Previously MTS1 / Staff Software Engineer')
  text=text.replace('content="#0f172a"','content="#236c5b"')
  text=text.replace('<p>&copy; Ishan Shah. Built with GitHub Pages.</p>','<p>&copy; Ishan Shah. <span>Professional record as of October 19, 2026.</span></p>')
  text=text.replace('<img class="profile-photo"','<img decoding="async" class="profile-photo"')
  text=re.sub(r'<script type="application/ld\+json">.*?</script>', '',text,flags=re.S)
  canonical=c.BASE+('' if name=='index' else template.name)
  schema={'@context':'https://schema.org','@graph':[{'@type':'WebSite','@id':c.BASE+'#website','url':c.BASE,'name':'Ishan Shah'},{'@type':'Person','@id':c.BASE+'#ishan-shah','name':'Ishan Shah','jobTitle':'Senior Software Engineer','url':c.BASE,'image':c.BASE+'assets/profile.jpg','worksFor':{'@type':'Organization','name':'PayPal, Inc.'},'sameAs':['https://www.linkedin.com/in/ishandshah/','https://github.com/ishandshah','https://sessionize.com/ishan-shah/']},{'@type':'WebPage','url':canonical,'name':re.search(r'<title>(.*?)</title>',text).group(1),'dateModified':c.AS_OF,'isPartOf':{'@id':c.BASE+'#website'},'about':{'@id':c.BASE+'#ishan-shah'}}]}
  if name=='writing':
   schema['@graph'].append({'@type':'ItemList','name':'Technical publications','itemListElement':[{'@type':'ListItem','position':i+1,'item':{'@type':'Article','headline':p['title'],'url':p['url'],'datePublished':p['date'],'author':([{'@type':'Person','name':'@hacker86245963'},{'@id':c.BASE+'#ishan-shah'}] if p['id']=='best-ai-fix' else {'@id':c.BASE+'#ishan-shah'}),'publisher':{'@type':'Organization','name':p['publisher']}}} for i,p in enumerate(c.PUBLICATIONS)]})
  for asset in ['assets/css/styles.css','assets/js/main.js']:
   digest=hashlib.sha256((ROOT/asset).read_bytes()).hexdigest()[:10]
   text=text.replace(asset+'"',asset+'?v='+digest+'"')
